import pandas as pd


def run(inputs: dict) -> dict:
    orders = inputs["orders"].copy()
    ref_customers = inputs["ref_customers"].copy()
    ref_skus = inputs["ref_skus"].copy()

    # Deduplicate reference tables on their key columns, keeping the first
    # occurrence (tie-break rule: first row wins).
    ref_customers_dedup = ref_customers.drop_duplicates(subset="customer_id", keep="first")
    ref_skus_dedup = ref_skus.drop_duplicates(subset="sku", keep="first")

    cust_status = dict(zip(ref_customers_dedup["customer_id"], ref_customers_dedup["status"]))
    sku_info = ref_skus_dedup.set_index("sku")[["discontinued", "allowed_countries"]].to_dict(orient="index")

    def classify(row):
        cid = row["customer_id"]
        if cid not in cust_status:
            return "CUST_UNKNOWN"

        status = cust_status[cid]
        if status != "ACTIVE":
            return "CUST_INACTIVE"

        sku = row["sku"]
        if sku not in sku_info:
            return "SKU_UNKNOWN"

        info = sku_info[sku]
        if info["discontinued"] == 1:
            return "SKU_DISC"

        allowed = info["allowed_countries"]
        if pd.notna(allowed):
            allowed_str = str(allowed).strip()
            if allowed_str != "":
                members = [m.strip() for m in allowed_str.split(",")]
                ship_country = row["ship_country"]
                if pd.isna(ship_country):
                    ship_country_cmp = ship_country
                else:
                    ship_country_cmp = str(ship_country).strip()
                if ship_country_cmp not in members:
                    return "CTRY_BLOCKED"

        return None

    if len(orders) == 0:
        reason = pd.Series([], dtype=object, index=orders.index)
    else:
        reason = orders.apply(classify, axis=1)

    clean_mask = reason.isna()

    orders_clean = orders[clean_mask].reset_index(drop=True)

    orders_rejects = orders[~clean_mask].copy()
    orders_rejects["reason_code"] = reason[~clean_mask]
    orders_rejects = orders_rejects.reset_index(drop=True)

    return {
        "orders_clean": orders_clean,
        "orders_rejects": orders_rejects,
    }
